CREATE OR REPLACE FUNCTION public.can_view_factory_cost(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _uid IS NOT NULL AND _uid=auth.uid() AND EXISTS(SELECT 1 FROM public.profiles WHERE auth_user_id=_uid AND is_active) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_uid AND role::text=ANY(ARRAY['production_head','head_operations','managing_director','finance_director','sales_director','architecture_director','super_admin','finance_manager','head_of_projects','planning_head','quantity_surveyor','costing_engineer'])) $$;
CREATE OR REPLACE FUNCTION public.can_read_factory(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _uid IS NOT NULL AND _uid=auth.uid() AND (public.can_write_factory(_uid) OR public.can_view_factory_cost(_uid)) $$;
CREATE FUNCTION public._factory_can_boq() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.profiles WHERE auth_user_id=auth.uid() AND is_active) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role::text=ANY(ARRAY['managing_director','finance_director','sales_director','architecture_director','super_admin','finance_manager','head_of_projects','planning_head','quantity_surveyor','costing_engineer'])) $$;
REVOKE ALL ON FUNCTION public._factory_can_boq() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public._factory_can_boq() TO service_role;
DO $p$ DECLARE d text; BEGIN d:=pg_get_functiondef('public.get_boq_work_locations(uuid)'::regprocedure); d:=replace(d,'auth.uid() IS NULL OR NOT public.can_view_running_bill(auth.uid())','NOT public._factory_can_boq()'); EXECUTE d; d:=pg_get_functiondef('public.set_boq_work_location(uuid,text)'::regprocedure); d:=replace(d,'auth.uid() IS NULL OR NOT public.can_view_running_bill(auth.uid())','NOT public._factory_can_boq()'); EXECUTE d; END $p$;